    [200+Math.sin(t*0.25+6)*110, 220+Math.cos(t*0.45+3)*60, 0.05, 2.4, 0.65]
  ];
  let aS = 0, iS = 0, cS = 0, wSum = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    cS += Math.cos(d*f*0.5 - t*sp*0.8 + 0.7) * w;
    wSum += w;
