  const act = aS/wSum, inh = iS/wSum, cross = cS/wSum;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.08+t*0.5)*Math.cos(sy*0.06-t*0.7)*0.15;
  const cx = 240, cy = 120;
