  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + coupling)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.2-t*0.3)*Math.cos(sy*0.18+t*0.4)*0.3)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+sy*0.2+t*3)*Math.cos(sx*0.25-sy*0.3-t*2.5)*0.08;
